package com.fitbite.ai;
import com.fitbite.dto.AiDtos.*; import com.fitbite.entity.*; import com.fitbite.rag.RecipeRetriever; import com.fitbite.repository.ChatHistoryRepository; import com.fitbite.service.CurrentUserService; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.MediaType; import org.springframework.stereotype.Service; import org.springframework.web.reactive.function.client.WebClient; import java.time.Instant; import java.util.*;
@Service public class AiService {private final RecipeRetriever retriever;private final CurrentUserService current;private final ChatHistoryRepository history;private final WebClient web;private final String key,model,baseUrl;public AiService(RecipeRetriever retriever,CurrentUserService current,ChatHistoryRepository history,@Value("${app.ai.base-url:}")String base,@Value("${app.ai.api-key:}")String key,@Value("${app.ai.model:}")String model){this.retriever=retriever;this.current=current;this.history=history;this.key=key;this.model=model;this.baseUrl=base;this.web=WebClient.builder().baseUrl(base==null?"":base).build();}
 public ChatResponse chat(String message){var ctx=retriever.retrieve(message);String context=ctx.stream().map(r->r.getName()+" | "+r.getCalories()+" kcal | protein "+r.getProtein()+"g | ingredients: "+r.getIngredients().stream().map(x->x.getIngredient().getName()).reduce((a,b)->a+", "+b).orElse("")).reduce((a,b)->a+"\n"+b).orElse("No matching recipes found.");String answer;boolean enabled=key!=null&&!key.isBlank()&&model!=null&&!model.isBlank()&&baseConfigured();if(enabled){answer=callLlm(message,context);}else{answer="Based on the FitBite recipe knowledge base, these are the closest matches:\n\n"+context+"\n\nI can provide more contextual answers when an LLM provider is configured. FitBite does not diagnose conditions or prescribe treatment.";}history.save(ChatHistory.builder().user(current.get()).userMessage(message).assistantMessage(answer).build());return new ChatResponse(answer,ctx.stream().map(r->new ChatMessage("context",r.getName(),Instant.now())).toList(),enabled);}
 private boolean baseConfigured(){return baseUrl!=null&&!baseUrl.isBlank();} private String callLlm(String message,String context){try{Map<String,Object> body=Map.of("model",model,"messages",List.of(Map.of("role","system","content","You are FitBite AI. Use the supplied recipe context. Do not diagnose, prescribe, or claim foods cure disease. Give practical recipe and nutrition guidance."),Map.of("role","user","content",message+"\n\nRecipe context:\n"+context)));Map<?,?> res=web.post().contentType(MediaType.APPLICATION_JSON).header("Authorization","Bearer "+key).bodyValue(body).retrieve().bodyToMono(Map.class).block();Object choices=res==null?null:res.get("choices");if(choices instanceof List<?> list&&!list.isEmpty()){Object first=list.get(0);if(first instanceof Map<?,?> m&&m.get("message") instanceof Map<?,?> mm)return String.valueOf(mm.get("content"));}}catch(Exception ignored){}return "I could not reach the configured AI provider right now. Here are the retrieved FitBite recipes:\n\n"+context;}
}
